    const fib=K.grp('fibrin',{p:[.4,1.25,0]});for(let i=0;i<16;i++){const a=V(rn(-.7,.7),rn(-.15,.15),rn(-.6,.6)),b=V(rn(-.7,.7),rn(-.15,.15),rn(-.6,.6));K.tube('fibrin',[a,a.clone().lerp(b,.5).add(V(0,rn(-.1,.1),0)),b],.012,0xFDE68A,{to:fib,seg:12})}fib.scale.setScalar(.01);
