        if(o.userData.part==='platelet'&&S.clot>0){if(!home.has(o))home.set(o,V(.4+rn(-.5,.5),1.1+rn(-.1,.08),rn(-.45,.45)));o.position.lerp(home.get(o),Math.min(1,dt*1.5*S.clot));continue}
