      const log=K.grp('log',{p:[2.3,0,0]});K.box('log',[0,.3,0],[.6,.4,.3],0x343A40,{to:log,gloss:1});const scr=panel(T3,K,'log',[0,.35,.16],.5,.3,(x,W,H,t=0)=>{x.fillStyle='#101828';x.fillRect(0,0,W,H);x.strokeStyle='#69DB7C';x.lineWidth=4;x.beginPath();for(let i=0;i<40;i++){const px=i/39*W,py=H*.85-H*.7*(1-Math.exp(-i/12-t*0))*(.6+.4*Math.sin(i/6+t));i?x.lineTo(px,py):x.moveTo(px,py)}x.stroke()},{to:log,r:[0,0,0]});K.tube('log',[V(0,.3,-.15),V(-.3,.2,-.4),V(-.5,.5,-.3)],.015,0x212529,{to:log});
