    // graphs and evaluation
    K.box(null,[0,1.35,-.5],[5.6,2.6,.05],0xFFFFFF,{gloss:1});const P=(x,y)=>V(-2.5+x*5,.35+y*2.1,-.45);K.arrow(null,P(0,0).toArray(),P(1.02,0).toArray(),0x212529,{w:.015});K.arrow(null,P(0,0).toArray(),P(0,1.03).toArray(),0x212529,{w:.015});txt(T3,K,'Independent variable (unit) →',P(.75,-.07).toArray(),{h:.1,bg:false,c:'#495057'});txt(T3,K,'Dependent variable (unit)',P(.15,1.06).toArray(),{h:.1,bg:false,c:'#495057'});
