    const lob=own(K.tube('lob',[P(0,.06),P(1,1.04)],.018,0x2F9E44,{seg:4}));const tri=K.grp('grad',{});const t1=link(T3,K,'grad',P(.2,.26),P(.8,.26),0x7048E8,.01),t2=link(T3,K,'grad',P(.8,.26),P(.8,.86),0x7048E8,.01);tri.add(t1,t2);const gl=txt(T3,K,'',P(.86,.55).toArray(),{h:.12,part:'grad',bg:'#F3F0FF'});
