      const qL=own(K.sph('q',[1.8,.25,-.6],.15,0x40C057,{glass:.4,mo:{emissive:0x40C057,emissiveIntensity:0}})),qbL=own(K.sph('q',[1.8,.25,.6],.15,0xFA5252,{glass:.4,mo:{emissive:0xFA5252,emissiveIntensity:0}}));txt(T3,K,'Q',[2.1,.3,-.6],{h:.18,part:'q',bg:false});txt(T3,K,'Q̄',[2.1,.3,.6],{h:.18,part:'q',bg:false});
      let Q=0,seq=0;const tb=txt(T3,K,'',[0,1.0,0],{h:.12,part:'q',bg:'#F8F9FA'});const upd=()=>{if(ex)readout(ex,'Two NOR gates feed each other’s outputs back. A pulse on <b>S</b> sets Q = 1; a pulse on <b>R</b> resets Q = 0. When both inputs return to 0, the feedback holds the output: the latch <b>remembers</b> one bit. S = R = 1 is the forbidden state. Truth table: S R → Q: 0 0 → no change, 1 0 → 1, 0 1 → 0.')};
      const tick=dt=>{S.t+=dt;const ph=(S.t*.25)%1,st=ph<.15?'S':ph<.45?'hold':ph<.6?'R':'hold';if(st==='S')Q=1;if(st==='R')Q=0;sb.material.color.set(st==='S'?0x40C057:0x868E96);rb.material.color.set(st==='R'?0xFA5252:0x868E96);qL.material.emissiveIntensity=Q?1.5:0;qbL.material.emissiveIntensity=Q?0:1.5;tb.userData.set(`S=${st==='S'?1:0} R=${st==='R'?1:0} → Q=${Q}${st==='hold'?' (remembered)':''}`);return true};
