    flux:[['field','Magnetic field','Flux density B.'],['loop','Coil','Area A, N turns.'],['normal','Normal','At angle θ to the field.'],['graph','Flux linkage','NBA cos θ.']],
    gen:[['coil','Rotating coil','Turned by the handle.'],['magnet','Magnets','Make the field.'],['rings','Slip rings / commutator','Connect to the circuit.'],['scope','Output','a.c. or pulsing d.c.']],
