    bal:[['magnet','Magnet on the balance','The field is between its poles.'],['wire','Fixed wire','Carries current I.'],['scale','Balance','Reading changes by F/g.'],['graph','F–I graph','Gradient BL.']],
    bqv:[['tube','Fine-beam tube','Low-pressure gas glows.'],['coils','Helmholtz coils','Uniform field.'],['beam','Electron beam','A circle.'],['gun','Electron gun','Sets the speed.']],
