      const B=gboard(T3,K,[2.0,1.3,-.5],1.9,1.4,'θ','NΦ',{id:'graph'});B.line('graph',[...Array(41)].map((_,i)=>[i/40,.5+.45*Math.cos(i/40*TAU)]),0x1C7ED6);const dot=own(K.sph('graph',[0,0,0],.06,0xE03131,{to:B.g}));const lab=txt(T3,K,'',[0,2.0,0],{h:.13,part:'graph',bg:'#F8F9FA'});
