    const prop=K.grp('prop',{p:[0,0,0]});K.box('prop',[0,.1,0],[.5,.08,.5],0x868E96,{to:prop});K.cyl('prop',[0,(Y0-.06+.14)/2,0],.025,Y0-.2,0x495057,{to:prop});K.cone('prop',[0,Y0-.08,0],.07,.12,0x495057,{to:prop});let tilt=0;
