      const bp=K.sph('a',P(...b),.06,0x495057,{gloss:1}),bl=txt(T3,K,'b = −1 − 0.5i',P(b[0]-.3,b[1]-.3,.06),{h:.13,part:'a'}),loc=live(T3,K,'locus',0x7048E8,.03),reg=area(T3,K,'locus',0xB197FC,.3),z=K.sph('z',[0,0,0],.07,0xE03131,{gloss:1}),zl=txt(T3,K,'z',[0,0,0],{h:.15,part:'z',c:'#C92A2A'}),d1=live(T3,K,'dist',0xF76707,.015),d2=live(T3,K,'dist',0x2F9E44,.015),dl=txt(T3,K,'',[0,0,0],{h:.13,part:'dist'}),hole=K.tor('a',P(...a),.06,.015,0x7048E8,{});
