      const q=own(K.sph('buyer',[1.3,1.25,0],.12,0xFAB005,{}));txt(T3,K,'?',[1.3,1.25,.15],{h:.18,part:'buyer'});const lem=own(K.sph('seller',[-.2,.9,0],.12,0xFFE066,{}));const lab=txt(T3,K,'',[0,1.8,0],{h:.13,part:'label'});
