    future:[['globe','The world','Centres of power.'],['paths','Pathways','Three futures.']],
    conflict:[['sea','South China Sea','Overlapping claims.'],['claims','Claims','Nine-dash line and EEZs.'],['ships','Naval patrols','Power projection.'],['nato','Cold War legacy','Alliances.']],
