      const C=['Norway','UK','Brazil','India','China','Saudi Arabia','N Korea'],SC=[[.98,.95],[.9,.92],[.7,.65],[.66,.55],[.25,.7],[.2,.65],[.03,.3]];const B=bars(T3,K,'index',[1.4,0,0],C,{gap:.4,w:.26,scale:1.6,cols:C.map(()=>0x1C7ED6)});
