const dotsOn=(K,id,a,b,c,n=3)=>[...Array(n)].map(()=>own(K.sph(id,[0,0,0],.045,c,{mo:{emissive:c,emissiveIntensity:.5}})));
const moveDots=(ds,a,b,t,sp=.3)=>ds.forEach((d,i)=>{const u=(t*sp+i/ds.length)%1;d.position.set(lerp(a[0],b[0],u),lerp(a[1],b[1],u)+Math.sin(u*Math.PI)*.35,lerp(a[2],b[2],u))});

