      const upd=()=>{const m=40+S.a*60,F=m*9.81,soft=.3+S.b*.7;P.forEach(o=>{const p=F/o.A;const d=Math.min(.28,p/1e6*soft*.25+(o.A<.01?.2*soft:0));o.g.position.y=.3-d;o.l.userData.set(`${p>1e5?r0(p/1000)+' kPa':r1(p/1000)+' kPa'}`)});
        if(ex)readout(ex,`Weight ${r0(F)} N (mass ${r0(m)} kg) · pressure p = F ÷ A · boots (0.06 m²): <b>${r1(F/.06/1000)} kPa</b> · snowshoes (0.4 m²): <b>${r1(F/.4/1000)} kPa</b> — you stay on top · stiletto heel (0.004 m², one heel): <b>${r0(F/.004/1000)} kPa</b> — sinks in and dents floors · same force, bigger area → smaller pressure (tractor tyres, foundations, camels’ feet); smaller area → bigger pressure (knives, nails, drawing pins) · elastic objects spring back when the force is removed; moments = force × perpendicular distance`)};
