const ks=new Set(R.map(r=>r[1]));
for(const [k,L] of Object.entries(LIB)){const prev=L.first&&L.first.maths;if(!ks.has(k)&&!prev)continue;
  L.first=L.first||{};L.first.maths={source:'(?!)',test:t=>{const r=route(t);return r?r[1]===k:!!(prev&&prev.test(t))}};
  if(ks.has(k)){const p0=L.pick;L.pick=t=>{const r=route(t);return r&&r[1]===k?r[2]:typeof p0==='function'?p0(t):undefined}}}
for(const r of R){const L=LIB[r[1]];if(!L)console.warn('mathmap: no model',r[1]);else if(r[2]&&L.variants&&L.variants.length&&!L.variants.some(x=>x[0]===r[2]))console.warn('mathmap: no view',r[1],r[2])}
L3.MATHROUTE=route;
