  const wrap=(px,py,r,f)=>{for(const dx of [-N,0,N])for(const dy of [-N,0,N]){if(px+dx+r<0||px+dx-r>N||py+dy+r<0||py+dy-r>N)continue;f(px+dx,py+dy)}};
