    sweatM=wet(T3,0x8EC3EA,{folds:10,var:.06,rough:.3,wet:.8,seed:155}),hairM=wet(T3,0x3A2416,{folds:20,var:.06,rough:.35,wet:.5,seed:156}),folM=wet(T3,0xE2A386,{lob:60,rough:.4,wet:.5,op:.75,seed:157}),
    sebM=wet(T3,0xF0DC9C,{lob:60,rough:.35,wet:.6,seed:158}),musM=wet(T3,0xB03A35,{folds:30,rough:.45,wet:.45,seed:159}),art=wet(T3,0xC0302E,{veins:2,rough:.3,wet:.8,seed:160}),
    ven=wet(T3,0x4F5BB8,{veins:2,rough:.3,wet:.8,seed:161}),nerveM=wet(T3,0xF1C84B,{folds:12,rough:.3,wet:.75,seed:162}),pac=wet(T3,0xF5E9D0,{lob:40,var:.05,rough:.3,wet:.7,op:.8,seed:163});
  // epidermis: living layer and the flaky horny layer on top; ridges dip into the dermis
  const ridge=new T3.PlaneGeometry(3.6,2,72,40);ridge.rotateX(-Math.PI/2);{const P=ridge.attributes.position;for(let i=0;i<P.count;i++){const x=P.getX(i),z=P.getZ(i);P.setY(i,-.06*Math.abs(Math.sin(x*5+Math.sin(z*3)))-.02)}ridge.computeVertexNormals()}
  mesh(K,'epi',new T3.BoxGeometry(3.6,.2,2,24,1,14),epiM,[0,1.0,0]);mesh(K,'epi',new T3.BoxGeometry(3.6,.07,2,24,1,14),corn,[0,1.135,0]);mesh(K,'epi',ridge,Object.assign(epiM.clone(),{side:T3.DoubleSide}),[0,.9,0]);
