  const fl=new T3.InstancedMesh(new T3.SphereGeometry(1,20,14),fatM,80),mm=new T3.Matrix4();for(let i=0;i<80;i++){const s=.13+r()*.08;mm.compose(V(rn(-1.7,1.7),rn(-.95,-.6),rn(-.9,.9)),new T3.Quaternion(),V(s*1.15,s*.8,s));fl.setMatrixAt(i,mm)}fl.instanceMatrix.needsUpdate=true;K.put(null,fl);
