  mesh(K,'sweat',tube(T3,coil,.045,{rad:14,seg:200}),sweatM,null,{to:sweat});const duct=[];for(let k=0;k<=30;k++){const t=k/30;duct.push([Math.sin(t*14)*.05*(t>.6?1:.3),-.25+t*1.42,Math.cos(t*14)*.05*(t>.6?1:.3)])}
