  mesh(K,'hair',sculpt(T3,(x,y,z)=>[x*.11,y*.1,z*.11],{seg:32}),folM,[0,-.58,0],{to:hair});mesh(K,'hair',tube(T3,[[0,-.5,0],[0,.3,0],[0,.9,.02],[.05,1.4,.05]],u=>.032-.01*u,{rad:12}),hairM,null,{to:hair});
  mesh(K,'hair',gland(T3,[.1,.08,.08],5,.2),sebM,[-.13,.1,0],{to:hair});const ere=mesh(K,'hair',tube(T3,[[.05,-.15,0],[.18,.05,0],[.32,.32,0]],.03,{rad:12}),musM,null,{to:hair});
