  const vs=K.grp('vessel');const vt=mesh(K,'vessel',tube(T3,[[-1.8,.55,.5],[0,.6,.5],[1.8,.55,.5]],.06,{rad:16}),art,null,{to:vs});mesh(K,'vessel',tube(T3,[[-1.8,-.4,.5],[0,-.45,.5],[1.8,-.4,.5]],.08,{rad:16}),ven,null,{to:vs});
