        nucM=wet(T3,0x8E9A86,{lob:30,var:.08,rough:.35,wet:.6,seed:174}),xyM=Object.assign(wet(T3,0x9A6A3C,{folds:30,var:.1,rough:.45,wet:.4,seed:175}),{side:T3.DoubleSide}),phM=wet(T3,0xD9E6A8,{lob:30,var:.06,rough:.35,wet:.6,op:.7,seed:176}),
        bsM=wet(T3,0xE8F2D2,{lob:30,var:.06,rough:.3,wet:.7,op:.5,seed:177}),gcM=wet(T3,0x5DAE58,{lob:30,var:.08,rough:.3,wet:.7,seed:178});
      // chloroplasts: lens-shaped, dark green and glossy (instanced)
      const chlM=new T3.MeshPhysicalMaterial({color:0x2E7D32,roughness:.35,clearcoat:.6,emissive:0x2F9E44,emissiveIntensity:.15}),lens=new T3.SphereGeometry(1,16,12);lens.scale(1,.45,.7);
      const lensSet=(id,pts,s)=>{const im=new T3.InstancedMesh(lens,chlM,pts.length),m=new T3.Matrix4();pts.forEach((p,i)=>{m.compose(V(...p),new T3.Quaternion().setFromEuler(new T3.Euler(rn(0,3),rn(0,3),rn(0,3))),V(s,s,s));im.setMatrixAt(i,m)});im.instanceMatrix.needsUpdate=true;return K.put(id,im)};
