    const upd=()=>{if(ex)readout(ex,S.ac>.5?'<b>Loose chromatin</b>: histones acetylated, DNA not methylated → transcription factors bind → <b>gene ON</b>':'<b>Tight chromatin</b>: DNA methylated, histones deacetylated → transcription factors can’t reach the DNA → <b>gene OFF</b>')};
