  const bodyM=[wet(T3,0xC9C3B6,{lob:80,var:.1,rough:.9,wet:0,sheen:.6,seed:171}),wet(T3,0x2A2622,{lob:80,var:.1,rough:.9,wet:0,sheen:.6,seed:172})];
