    fishes.forEach((f,i)=>{const dead=t>.8;f.position.set(-.3+((ph*.2+i*.37)%1)*2.6*(dead?0:1)+(dead?i*.42:0),dead?.66:.35+Math.sin(ph*2+i)*.06,-.9+i*.35);f.rotation.set(dead?Math.PI:0,0,0)});
