    const wood=pm(T3,{color:0x9A9A9A,map:woodTex(T3,'#8A5E36',951),roughness:.8});
    for(let i=0;i<=10;i++){const x=-2.95+i*.59;mesh(K,null,new T3.BoxGeometry(.07,.6,.07),wood,[x,.3,-1.45])}for(const z of [-1.1,-.5,.1,.7])for(const s of [-1,1])mesh(K,null,new T3.BoxGeometry(.07,.6,.07),wood,[s*2.95,.3,z]);
