  const eM=wet(T3,0x2E9A4A,{lob:200,var:.1,rough:.4,wet:.4,sheen:0,bump:.008,seed:1502});mesh(K,'enzyme',lumpy(T3,.26,.55,.24,23),eM,EC.toArray());mesh(K,'enzyme',lumpy(T3,.3,.18,.26,24),eM,[EC.x,EC.y-.62,EC.z]);const glow=halo(T3,K,'enzyme','90,240,120',1.1,[EC.x,EC.y-.62,EC.z]);
