// ---------- Biology mapping: which model claims which subtopic first, so every subtopic in a topic gets its own model ----------
(()=>{const LIB=L3.LIB;
const F=(k,re,s='biology')=>{const L=LIB[k];if(!L)return;L.first=L.first||{};L.first[s]=L.first[s]?new RegExp(L.first[s].source+'|'+re.source,'i'):new RegExp(re.source,'i')};
const P=(k,fn)=>{const L=LIB[k];if(!L)return;const p0=L.pick;L.pick=t=>{const r=fn(t);return r!==undefined?r:typeof p0==='function'?p0(t):undefined}};
// cells, division, stem cells
F('stem',/cell differentiation|root tip squash|percentile|specialised cells|specialisation of cells/);
F('membrane',/^transport in cells/);P('membrane',t=>/^transport in cells/i.test(t)?'diffusion':undefined);
F('gameto',/gametogenesis/);
// food
F('foodlab',/food tests|tests for sugars|calorimetry|energy in food|balanced diet|diet,? exercise and health/);
// microbes and disease
F('pathogen',/viruses: structure and replication|pathogens, transmission and named diseases|communicable diseases in detail/);
P('pathogen',t=>/viruses: structure/i.test(t)?'virus':/pathogens, transmission and named diseases|communicable diseases in detail/i.test(t)?'malaria':undefined);
F('immx',/viruses: structure, replication and hiv|monoclonal antibod|non-specific defences: barriers, phagocytosis, inflammation and interferon|cell recognition and the immune|antibiotic resistance and controlling|transmission and control of disease|plant defences against pathogens/);
F('micro',/aseptic technique|measuring microbial growth|zones of inhibition/);
// gene technology, cloning
F('genetech',/dna sequencing|sequencing methods|bioinformatics|gene therapy|dna probes?|genetic screening|genome projects?|human genome|genetic testing|embryo screening|personalised medicine/);
F('gmo',/ethical,? social and economic issues of genetic|gm crops|genetically modified crops/);
F('clonex',/cloning in plants|cloning plants|vegetative propagation/);
F('dnacode',/^dna and protein synthesis/);
// ecology, populations, biodiversity, evolution, classification
P('ecosystem',t=>/^nutrient cycles/i.test(t)?'nitrogen':undefined);
F('pollute',/eutrophication|bioaccumulation|biomagnification/);
F('biodiv',/conservation methods|why biodiversity matters|sustainable management of ecosystems|communities and adaptations|biodiversity and human impact|human activities that reduce biodiversity|indicator species|effect of an environmental factor on the distribution/);
F('climate',/climate change and its effects on ecosystems/);
F('popn',/populations in ecosystems|hardy.weinberg|genetic drift|founder effect|population bottleneck/);
F('evox',/artificial selection|selective breeding|types of natural selection|binomial nomenclature|taxonomic hierarch/);
P('evolution',t=>/evidence for evolution/i.test(t)&&!/variation, evolution/i.test(t)?'fossils':undefined);
// control systems, homeostasis
F('sensory',/photoreceptors|rod and cone|stimuli,? receptors and plant|pacinian/);
F('pgr',/commercial uses of plant growth|plant responses: leaf abscission|effect of plant growth substances/);
F('inherit',/autosomal linkage|epistasis|chi.squared test for genetic/);
F('endocrine',/^control of blood glucose/);
F('homeo',/principles of homeostasis|blood water potential|urine analysis/);
// transport and exchange
F('heartlab',/daphnia/);
F('cvd',/cardiovascular disease/);
P('heart',t=>/mass transport in animals/i.test(t)?'vessels':undefined);
F('gasx',/dissection of a gas exchange/);
F('membx',/cell signalling|membrane permeability|beetroot/);
F('resp',/respiratory substrates|respiratory quotient/);
F('photolab',/chromatography of photosynthetic|rate of photosynthesis and dehydrogenase|effect of light intensity on the rate of photosynthesis/);
F('plantx',/mineral ion|transpiration with a potometer|transpiration and stomata|plant tissues and transport/);
// practical and maths skills
F('biolab',/apparatus and techniques: measurement, serial dilution|planning and designing investigations/);
F('biomath',/arithmetic skills|mathematical skills: si units|processing and presenting data|surface area to volume ratio and gas exchange/);
F('sci',/evaluating data: accuracy, precision|evidence, peer review, risk and ethics|tables and graphs: plotting|^uncertainty, accuracy, precision, validity|working scientifically: hypotheses/);
P('sci',t=>/evaluating data: accuracy/i.test(t)?'prec':/evidence, peer review/i.test(t)?'safety':/^tables and graphs: plotting/i.test(t)?'graph':/^uncertainty, accuracy, precision, validity/i.test(t)?'uncert':/working scientifically: hypotheses/i.test(t)?'vars':undefined);
F('stats3d',/drawing conclusions and evaluating|statistical tests: mean, standard deviation/);
P('stats3d',t=>/drawing conclusions and evaluating/i.test(t)?'scatter':/statistical tests: mean, standard deviation/i.test(t)?'normal':undefined);
// remaining clashes
P('biodiv',t=>/balancing human needs/i.test(t)?'loss':undefined);
F('diabetes',/treatments? for diabetes/);
F('tfluid',/tissue fluid|blood clotting/);
P('pathogen',t=>/pathogens and disease: bacteria, viruses, fungi/i.test(t)?'fungus':undefined);
F('pathogen',/pathogens and disease: bacteria, viruses, fungi/);
F('conflict',/balancing human needs and conservation/);
})();
// ---------- 3D model library: last matching fixes (subtopics that had no 3D model) ----------
(()=>{const LIB=L3.LIB;const addMatch=(k,re,s)=>{const L=LIB[k];if(!L||!L.match)return;L.match[s]=L.match[s]?new RegExp(L.match[s].source+'|'+re.source,'i'):re};
addMatch('biome',/ocean pollution|marine protected|blue economy|ocean management|ocean acidification/,'geography');if(LIB.biome){const p0=LIB.biome.pick;LIB.biome.pick=t=>/\boceans?\b/i.test(t)?'reef':p0(t)}
addMatch('quake',/impacts and responses/,'geography');addMatch('debates',/\biq test|nation of morons|intelligence testing/,'psychology');})();
(()=>{const L=L3.LIB.quake;if(L){L.not=L.not||{};L.not.physics=L.not.physics?new RegExp(L.not.physics.source+'|seismic waves and the structure','i'):/seismic waves and the structure/i}})();
(()=>{const L=L3.LIB.circuit;if(L){L.not=L.not||{};L.not.physics=L.not.physics?new RegExp(L.not.physics.source+'|current balance','i'):/current balance/i}})();
